/**
 * POST /api/chat
 * Body: { event?: string, message?: string, history?: {role, content}[] }
 *
 * The incident context always comes from the server-side state machine,
 * never from the client, so the browser cannot steer the AI off-playbook.
 * The response carries text only: action buttons are rendered from the
 * playbook by the UI, never generated by the model.
 */
const express = require('express');
const config = require('../config');
const gemini = require('../services/geminiService');
const incidents = require('../services/incidentService');
const { rateLimit } = require('../middleware/security');
const { asyncHandler } = require('../middleware/errorHandler');

const router = express.Router();

function sanitizeHistory(history) {
  if (!Array.isArray(history)) return [];
  return history
    .filter((m) => m && ['user', 'assistant'].includes(m.role) && typeof m.content === 'string')
    .slice(-20)
    .map((m) => ({ role: m.role, content: m.content.slice(0, 2000) }));
}

router.post(
  '/',
  rateLimit({ windowMs: config.rateLimit.windowMs, max: config.rateLimit.chatMax }),
  asyncHandler(async (req, res) => {
    const { event = 'USER_MESSAGE', message = '' } = req.body || {};

    if (event === 'USER_MESSAGE' && (typeof message !== 'string' || !message.trim())) {
      return res.status(400).json({ error: 'message is required' });
    }

    const state = await incidents.loadState();
    const result = await gemini.generateReply({
      event: String(event),
      message: String(message).slice(0, 1000),
      history: sanitizeHistory(req.body?.history),
      state,
    });

    return res.json({
      ...result,
      incidentId: state.incident?.id || null,
      phase: state.phase,
    });
  }),
);

module.exports = router;
